describe('Registration Form Email Validation', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display error message when submitting form with invalid email', () => {
    // Intercept the registration API call
    cy.intercept('POST', '/api/register').as('registerRequest');

    // Fill in the form with invalid email
    cy.get('[data-testid="email-input"]').type('not-an-email');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePassword123');
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Please enter a valid email address');

    // Verify form is not submitted
    cy.get('[data-testid="register-form"]').should('have.class', 'is-submitting');
    cy.get('[data-testid="register-form"]').should('not.have.class', 'is-valid');

    // Verify error state persists after form reset
    cy.get('[data-testid="reset-button"]').click();
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Please enter a valid email address');
  });

  it('should clear error message when form is validated with correct email', () => {
    // Intercept the registration API call
    cy.intercept('POST', '/api/register').as('registerRequest');

    // Fill in the form with valid email
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePassword123');
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message is cleared
    cy.get('[data-testid="email-error-message"]').should('not.exist');

    // Verify form is submitted successfully
    cy.get('[data-testid="register-form"]').should('not.have.class', 'is-submitting');
    cy.get('[data-testid="register-form"]').should('have.class', 'is-valid');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Registration successful');
  });
});
